DESCRIPTION = __doc__

logger = logging.getLogger(__name__)


def build_arg_parser(argparser=None):
    if argparser is None:
        argparser = argparse.ArgumentParser()

    argparser.description = DESCRIPTION
    argparser.formatter_class = argparse.RawTextHelpFormatter

    argparser.add_argument(
        "projects",
        type=str,
        help="Path to project or solution (.tsproj, .sln)",
        nargs="+",
    )

    argparser.add_argument(
        "-t",
        "--template",
        type=str,
        dest="templates",
        required=False,
        action="append",
        help=(
            f"Template filename with optional output filename. "
            f"In the form ``input_filename[{os.pathsep}output_filename]``."
            f"Defaults to '-' (standard input -> standard output)."
        ),
    )

    argparser.add_argument(
        "--macro",
        "-m",
        type=str,
        required=False,
        action="append",
        dest="macros",
        help="Define a macro for the template in the form MACRO=VALUE",
    )

    argparser.add_argument(
        "--debug",
        "-d",
        action="store_true",
        help="Post template generation, open an interactive Python session",
    )

    return argparser


def find_git_root(fn: pathlib.Path) -> Optional[pathlib.Path]:
    """Given a file, find the git repository root (if it exists)."""
    while fn:
        if (fn / ".git").exists():
            return fn
        fn = fn.parent


def _to_http_url(url: str) -> str:
    """Git over SSH -> GitHub https URL."""
    if url.startswith("git@github.com:"):
        _, repo_slug = url.split(":")
        return f"https://github.com/{repo_slug}"
    return url


def _to_doc_url(url: str) -> str:
    """Git over SSH -> GitHub https URL."""
    try:
        org, repo = _to_repo_slug(url).split("/")
        return f"https://{org}.github.io/{repo}"
    except Exception:
        return ""


def _to_tree_url(url: str, hash: str) -> str:
    """Get a github.com/org/repo/tree/master-style URL."""
    url = _to_http_url(url)
    if url.startswith("https://github.com"):
        return f"{url}/tree/{hash}"
    return url


def _to_repo_slug(url: str) -> str:
    """Get a org/repo from a full URL."""
    url = _to_http_url(url)
    github = "https://github.com/"
    if url.startswith(github):
        return url.split(github)[1]
    return url


def get_git_info(fn: pathlib.Path) -> dict[str, Any]:
    """Get the git hash and other info for the repository that ``fn`` is in."""
    if git is None:
        raise RuntimeError("gitpython not installed")
    repo = git.Repo(find_git_root(fn))
    urls = [url for remote in repo.remotes for url in remote.urls]
    repo_slugs = [_to_repo_slug(url) for url in urls]
    head_sha = repo.head.commit.hexsha
    if repo.git is not None:
        try:
            desc = repo.git.describe("--contains", head_sha)
        except git.GitCommandError:
            desc = repo.git.describe("--always", "--tags")
    else:
        desc = "unknown"

    return {
        "describe": desc or "unknown",
        "sha": head_sha,
        "repo_slug": repo_slugs[0] if repo_slugs else None,
        "repo_slugs": repo_slugs,
        "doc_urls": [_to_doc_url(url) for url in urls],
        "repo_urls": [_to_http_url(url) for url in urls],
        "tree_urls": [_to_tree_url(url, head_sha) for url in urls],
        "repo": repo,
    }


def project_to_dict(path: parser.AnyPath) -> dict[str, Any]:
    """
    Create a user/template-facing dictionary of project information.

    In the case of a tsproj or solution, returns keys solutions and projects.
    All other formats (such as .tmc) fall under the "others" key, leaving it up
    to the template to classify.
    """
    path = pathlib.Path(path)
    suffix = path.suffix.lower()

    if suffix in {".tsproj", ".sln"}:
        if suffix == ".sln":
            project_files = parser.projects_from_solution(path)
            solution = path
        else:
            project_files = [path]
            solution = None

        projects = {fn: parser.parse(fn) for fn in project_files}

        for fn, project in projects.items():
            try:
                project.git_info = get_git_info(fn)
            except Exception:
                project.git_info = {
                    "describe": "unknown",
                    "sha": "unknown",
                    "urls": [],
                    "links": [],
                    "repo_slug": "unknown",
                    "repo_slugs": [],
                    "doc_urls": [],
                    "repo_urls": [],
                    "tree_urls": [],
                    "repo": None,
                }

        solutions = {solution: projects} if solution is not None else {}

        return {
            "solutions": solutions,
            "projects": projects,
        }

    return {
        "others": {path: parser.parse(path)},
    }


def projects_to_dict(*paths) -> dict[str, dict[pathlib.Path, Any]]:
    """
    Create a user/template-facing dictionary of project information.

    Returns
    -------
    dict
        Information dictionary with keys::
            solutions - {solution_filename: [project_fn: {...}, ...], ...}
            projects - {project_filename: {...}, ...}
            others - {filename: {...}, ...}
    """
    result = {
        "solutions": {},
        "projects": {},
        "others": {},
    }
    for path in paths:
        for key, value in project_to_dict(path).items():
            result[key].update(value)
    return result


def get_jinja_filters(**user_config) -> dict[str, callable]:
    """All jinja filters."""

    if "delim" not in user_config:
        user_config["delim"] = ":"

    if "prefix" not in user_config:
        user_config["prefix"] = "PREFIX"

    def epics_prefix(obj: parser.TwincatItem) -> str:
        return stcmd.get_name(obj, user_config)[0]

    def epics_suffix(obj: parser.TwincatItem) -> str:
        return stcmd.get_name(obj, user_config)[1]

    def pragma(obj: parser.TwincatItem, key: str, default: str = "") -> str:
        item_and_config = pragmas.expand_configurations_from_chain([obj])
        if item_and_config:
            item_to_config = dict(item_and_config[0])
            config = pragmas.squash_configs(*item_to_config.values())
            return config.get(key, default)
        return default

    def title_fill(text: str, fill_char: str) -> str:
        return fill_char * len(text)

    return {key: value for key, value in locals().items() if not key.startswith("_")}


def get_symbols(plc) -> Generator[parser.Symbol, None, None]:
    """Get symbols for the PLC."""
    for symbol in plc.find(parser.Symbol):
        symbol.top_level_group = symbol.name.split(".")[0] if symbol.name else "Unknown"
        yield symbol


def get_symbols_by_type(plc: parser.Plc) -> dict[str, list[parser.Symbol]]:
    """Get symbols for the PLC."""
    symbols = plc.find(parser.Symbol, recurse=False)
    return parser.separate_by_classname(symbols)


# Defined in parser so that pytmc-db can use it too; re-exported here.
has_axis_link = parser.has_axis_link


@functools.lru_cache
def get_legacy_motors(plc: parser.Plc) -> list[parser.Symbol_ST_MotionStage]:
    """
    Find all valid legacy motors (ST_MotionStage) in the provided PLC.

    Criteria:
        - The symbol is of type Symbol_ST_MotionStage.
        - The symbol is not a pointer (i.e., is_pointer is False).
        - The symbol has a pytmc pragma (parser.has_pragma is True).

    For each returned motor, a dynamic attribute 'is_legacy_motor' is set to True,
    enabling template logic or further processing to easily distinguish legacy motors.

    Args:
        plc (parser.Plc): The parsed PLC object to examine.

    Returns:
        list[parser.Symbol_ST_MotionStage]:
            List of all valid legacy motor symbols from this PLC.
    """
    symbols = get_symbols_by_type(plc)
    st_motors = symbols.get("Symbol_ST_MotionStage", [])
    legacy = []
    for stage in st_motors:
        if motion_library.is_legacy_motor(stage) and parser.has_pragma(stage):
            stage.is_legacy_motor = True
            legacy.append(stage)
    return legacy


@functools.lru_cache
def get_stream_motors(plc: parser.Plc) -> list[parser.Symbol_FB_MotionStage]:
    """
    Find all valid stream (FB_MotionStage) motors in the given PLC.

    [existing docstring, then add:]

    For ARRAY[1..N] OF FB_MotionStageNC declarations, the parent array
    symbol is expanded into N per-element proxies via the same
    handle_array_complex machinery used by chains_from_symbol. Each
    proxy carries its own ``axis_link_override`` so the template's
    ``motor.nc_axis`` access resolves to the correct per-element axis.
    Scalar motion-FB symbols (the common case) pass through unchanged.
    """
    symbols = get_symbols_by_type(plc)
    fb_motors = symbols.get("Symbol_FB_MotionStage", [])
    stream = []
    for stage in fb_motors:
        if not motion_library.is_nc_mapped_motor(stage):
            continue
        # Expand array-of-FB symbols into per-element proxies.
        if getattr(stage, "array_dimensions", None):
            for elem in _expand_motor_array(stage):
                elem.is_legacy_motor = False
                stream.append(elem)
        else:
            stage.is_legacy_motor = False
            stream.append(stage)
    return stream


def _expand_motor_array(stage):
    """Yield per-element _ArrayItemProxy instances for an array-of-FB symbol.

    Mirrors the per-element axis-link resolution that
    ``pragmas.handle_array_complex`` performs for chains, so each
    proxy ends up with the same ``axis_link_override`` it would carry
    in the record-generation pipeline. Each proxy also carries a
    ``pvname_override`` derived from the ``expand-names`` (or
    ``expand``) pragma key, so ``stcmd.get_name`` resolves to the
    per-element role-based PV name (e.g. ``TST:MAL:MMS``) rather than
    the array-level pragma value (``TST:MAL``).

    When the array-level pragma sets ``nc-optional: true``, every proxy
    additionally receives ``nc_optional_override = True``. This stamp
    is read by ``_ArrayItemProxy.nc_to_plc_link`` and
    ``_ArrayItemProxy.nc_axis`` (in pytmc/parser.py): when no
    ``nctoplc`` link is found in the project for an element's
    axis-link value, those properties return ``None`` and an
    :class:`parser._AbsentNCAxis` stand-in (respectively) instead of
    raising. The element still appears in st.cmd; NC-derived fields
    (``AXIS_NO``, ``EGU``, ``PREC``, ...) render as empty strings.
    Useful when the NC link is established dynamically at runtime
    rather than statically in the TwinCAT project file.

    Only 1D arrays are supported, consistent with the ``axis-link``
    rejection of multi-dimensional arrays in handle_array_complex.
    """
    dims = stage.array_dimensions
    if len(dims) != 1:
        raise RuntimeError(
            f"Array-of-FB_MotionStage with {len(dims)} dimensions is not "
            f"supported ({stage.name!r}). Motion FBs must be declared as "
            f"1D arrays."
        )
    (low, high) = dims[0]

    # Read pv, axis-link, expand-names, expand, nc-optional, and
    # array: from the pragma.
    pv_root = None
    axis_link_setting = None
    expand_names_setting = None
    expand_setting = None
    nc_optional_setting = False
    array_setting = ""
    for raw in parser.get_pragma(stage, name="pytmc"):
        for line in raw.splitlines():
            line = line.strip()
            if line.lower().startswith("pv:"):
                pv_root = line.partition(":")[2].strip()
            elif line.lower().startswith("axis-link:"):
                axis_link_setting = line.partition(":")[2].strip()
            elif line.lower().startswith("expand-names:"):
                expand_names_setting = line.partition(":")[2].strip()
            elif line.lower().startswith("expand:"):
                expand_setting = line.partition(":")[2].strip()
            elif line.lower().startswith("array:"):
                # Mirrors handle_array_complex: subsets the motors
                # actually emitted into st.cmd. Only the outer (and
                # only) dimension applies for 1D motion FB arrays;
                # any `|`-separated trailing segments are rejected
                # below because motion FBs must be 1D.
                array_setting = line.partition(":")[2].strip()
            elif line.lower().startswith("nc-optional:"):
                # Truthy values opt the array out of NC-link validation;
                # see _ArrayItemProxy.nc_to_plc_link / nc_axis (parser.py)
                # for the consuming behavior.
                value = line.partition(":")[2].strip().lower()
                nc_optional_setting = value in ("true", "1", "yes")

    if axis_link_setting is None:
        raise RuntimeError(
            f"Array-of-FB {stage.name!r} reached _expand_motor_array "
            f"without an axis-link pragma — has_axis_link should have "
            f"filtered it out earlier."
        )

    # array: only applies to the (sole) outer dimension here; reject
    # `|`-separated multi-dim form on motion FBs to stay aligned with
    # handle_array_complex's 1D-only rule for axis-link.
    if "|" in array_setting:
        raise RuntimeError(
            f"Multi-dimensional array: selector {array_setting!r} is not "
            f"supported on motion FBs ({stage.name!r}); only the outer "
            f"dimension applies."
        )
    selected_indices = list(
        pragmas.parse_array_settings(array_setting, (low, high))
    )
    expected = len(selected_indices)
    bounds_label = (
        f"the array: slice requires {expected}"
        if array_setting
        else f"array bounds [{low}..{high}] require {expected}"
    )

    # Resolve axis-link per element (existing logic).
    if "," in axis_link_setting:
        axis_links = [
            e.strip() for e in axis_link_setting.split(",") if e.strip()
        ]
        if len(axis_links) != expected:
            raise RuntimeError(
                f"axis-link on {stage.name!r} has {len(axis_links)} entries "
                f"but {bounds_label}"
            )
    elif "%" in axis_link_setting:
        try:
            axis_links = [axis_link_setting % i for i in selected_indices]
        except (TypeError, ValueError) as ex:
            raise RuntimeError(
                f"Invalid axis-link format string {axis_link_setting!r} "
                f"on {stage.name!r}: {ex}"
            )
    else:
        raise RuntimeError(
            f"axis-link {axis_link_setting!r} on array {stage.name!r} has "
            f"no '%d' placeholder and is not a comma-separated list."
        )

    # Resolve per-element pvnames using the same precedence as
    # handle_array_complex: expand-names beats expand: beats numeric default.
    if expand_names_setting is not None:
        names = pragmas.parse_expand_names(
            expand_names_setting,
            (low, high),
            expected_count=expected if array_setting else None,
        )
        suffixes = [f":{n}" for n in names]
    elif expand_setting is not None:
        suffixes = [expand_setting % i for i in selected_indices]
    else:
        # Numeric default mirrors handle_array_complex's behavior.
        import math
        digits = math.floor(math.log10(high)) + 2
        suffixes = [(f":%.{digits}d") % i for i in selected_indices]

    pv_root = pv_root or ""

    for offset, idx in enumerate(selected_indices):
        proxy = parser._ArrayItemProxy(stage, idx)
        proxy.__dict__["axis_link_override"] = axis_links[offset]
        proxy.__dict__["pvname_override"] = pv_root + suffixes[offset]
        # Propagate the array-level nc-optional setting onto each proxy
        # so per-element nc_to_plc_link / nc_axis returns soft values
        # instead of raising when the link can't be resolved at TMC-
        # export time.
        if nc_optional_setting:
            proxy.__dict__["nc_optional_override"] = True
        yield proxy


@functools.lru_cache
def get_motors(plc: parser.Plc) -> List[Union[parser.Symbol_ST_MotionStage, parser.Symbol_FB_MotionStage]]:
    """
    Return all valid motors for the PLC by concatenating legacy and stream (FB) motors.
    Each entry is tagged via is_legacy_motor.
    """
    return get_legacy_motors(plc) + get_stream_motors(plc)


def get_plc_by_name(
    projects: dict[parser.AnyPath, parser.TcSmProject], plc_name: str
) -> tuple[Optional[parser.TcSmProject], Optional[parser.Plc]]:
    """
    Get a Plc instance by name.

    Parameters
    ----------
    projects : Dict[Path, parser.TcSmProject]
        The projects to search, as provided by pytmc template.
    plc_name : str
        The name of the PLC to search for.

    Returns
    -------
    project : parser.TcSmProject or None
        The project containing the PLC.
    plc : parser.Plc or None
        The PLC instance.
    """
    for _, project in projects.items():
        for plc in project.plcs:
            if plc.name == plc_name:
                return project, plc

    return None, None


@functools.lru_cache
def get_plc_record_packages(
    plc: parser.Plc,
    dbd: Optional[str] = None,
) -> tuple[list[RecordPackage], list[Exception]]:
    """
    Get EPICS record packages generated from a specific PLC.

    Returns
    -------
    records : list of RecordPackage
        Record packages generated.

    exceptions : list of Exception
        Any exceptions raised during the generation process.
    """
    if plc.tmc is None:
        return None, None

    try:
        packages, exceptions = db_process(
            plc.tmc,
            dbd_file=dbd,
            allow_errors=True,
            show_error_context=True,
        )
    except Exception:
        logger.exception("Failed to create EPICS records")
        return None, None

    return packages, exceptions


@functools.lru_cache
def get_nc(project: parser.TopLevelProject) -> parser.NC:
    """Get the top-level NC settings for the project."""
    try:
        (nc,) = list(project.find(parser.NC, recurse=False))
        return nc
    except Exception:
        return None


@functools.lru_cache
def get_data_types(project: parser.TwincatItem) -> list[dict]:
    """Get the data types container for the project."""
    data_types = getattr(project, "DataTypes", [None])[0]
    if data_types is not None:
        return list(summary.enumerate_types(data_types))
    return []


@functools.lru_cache
def get_boxes(project) -> list[parser.Box]:
    """Get boxes contained in the project."""
    return list(
        sorted(project.find(parser.Box), key=lambda box: int(box.attributes["Id"]))
    )


def _get_box_to_children(boxes: list[parser.Box]) -> dict[parser.Box, list[parser.Box]]:
    parent_to_children = {}

    for box in boxes:
        for child in box._children:
            if isinstance(child, parser.TcSmItem):
                (child_box,) = child.Box
            elif isinstance(child, parser.Box):
                child_box = child
            else:
                continue

            parent_to_children.setdefault(box, []).append(child_box)

    return parent_to_children


def _get_root_boxes(
    parent_to_children: dict[parser.Box, list[parser.Box]]
) -> list[parser.Box]:
    root = []
    for box in parent_to_children:
        for children in parent_to_children.values():
            if box in children:
                break
        else:
            root.append(box)
    return root


BoxHierarchy = dict[parser.Box, "BoxHierarchy"]


def get_box_hierarchy(project) -> BoxHierarchy:
    """
    Get boxes contained in the project in a hierarchical fashion.

    This is in the form: ``{box: {child: grandchild: {}}}``.
    """

    def recurse_children(box: parser.Box) -> BoxHierarchy:
        return {
            child: recurse_children(child) for child in parent_to_children.get(box, [])
        }

    boxes = get_boxes(project)
    parent_to_children = _get_box_to_children(boxes)
    return {
        root: recurse_children(root) for root in _get_root_boxes(parent_to_children)
    }


def _clean_link(link: parser.Link):
    """Clean None from links for easier displaying."""
    link.a = tuple(value or "" for value in link.a)
    link.b = tuple(value or "" for value in link.b)
    return link


@functools.lru_cache
def get_links(project: parser.TwincatItem) -> list[parser.Link]:
    """Get links contained in the project or PLC."""
    return list(_clean_link(link) for link in project.find(parser.Link))


def generate_records(
    plc: parser.Plc,
    path: Optional[parser.AnyPath] = None,
    dbd: Optional[parser.AnyPath] = None,
    allow_errors: bool = False,
    write_archive_file: bool = True,
    include_ethercat_state_db: bool = True,
    macro_substitutions: str | Mapping[str, str] | None = None,
) -> tuple[list[str], dict[str, Any]]:
    """
    Generate records from ``plc`` writing to ``path``.

    Optionally lint with ``dbd``.

    Parameters
    ----------
    plc : parser.Plc

    path : AnyPath, optional
        Defaults to {{plc.name}}.db

    dbd : parser.AnyPath, optional
        Lint the generated database file with the provided dbd.

    allow_errors : bool, optional
        Allow errors when generating the .db file.

    write_archive_file : bool, optional
        Write archive file to {{plc.name}}.archive

    include_ethercat_state_db : bool, optional
        Generate EtherCAT state and link records and their IOC-shell access config.
        Defaults to True. This can also be disabled by setting
        ``GENERATE_ETHERCAT_STATE_FILES=0`` in ``macro_substitutions``. The
        ``GENERATE_ETHERCAT_STATE_DB`` macro is supported as an alias. When
        generation is skipped, stale EtherCAT outputs next to ``path`` are
        removed.

    macro_substitutions : str or mapping, optional
        Database load macros from the IOC Makefile, used to measure expanded PV
        and alias name lengths. When a template omits these substitutions,
        PV-length checks and EtherCAT file generation are skipped. Checks are
        also skipped when referenced macros cannot be resolved; EtherCAT file
        generation requires ``PREFIX``.

    Returns
    -------
    filenames : list of str
        Database filenames.
    records : Dict[str, RecordPackage]
        Records by name.
    """
    if plc.tmc is None:
        return [], {}

    if path is None:
        path = f"{plc.name}.db"
        archive_path = f"{plc.name}.archive"
    else:
        archive_path = f"{path}.archive"

    macro_values = parse_epics_macro_substitutions(macro_substitutions)
    generate_ethercat_macro = macro_values.get(
        "GENERATE_ETHERCAT_STATE_FILES",
        macro_values.get("GENERATE_ETHERCAT_STATE_DB", ""),
    ).strip()
    generate_ethercat = (
        include_ethercat_state_db
        and macro_substitutions is not None
        and generate_ethercat_macro != "0"
    )
    missing_ethercat_macros = set()
    if generate_ethercat:
        missing_ethercat_macros = missing_epics_macro_substitutions(
            ["$(PREFIX)ECAT::State_RBV"], macro_values
        )
        generate_ethercat = not missing_ethercat_macros
        if missing_ethercat_macros:
            logger.warning(
                "Skipping EtherCAT file generation because database macros are "
                "missing: %s",
                ", ".join(sorted(missing_ethercat_macros)),
            )
    if not generate_ethercat:
        database_path = pathlib.Path(path)
        for stale_path in (
            database_path.with_name(f"{database_path.stem}_EtherCAT.db"),
            database_path.with_name(
                f"{database_path.stem}_ethercat_state_access.cmd"
            ),
        ):
            stale_path.unlink(missing_ok=True)

    packages, exceptions = get_plc_record_packages(plc, dbd=dbd)
    if exceptions and not allow_errors:
        logger.exception(
            "Linter errors - failed to create database. To create the database"
            " ignoring these errors, set allow_errors=True"
        )
        sys.exit(1)

    terminals = []
    ethercat_packages = []
    if generate_ethercat:
        terminals = ethercat.get_ethercat_terminals(plc.root)
        ethercat_packages = ethercat.create_ethercat_packages(
            terminals, macro_values
        )

    all_records = [
        record
        for package in [*packages, *ethercat_packages]
        for record in package.records
    ]
    if macro_substitutions is not None:
        record_pv_names = [
            name
            for record in all_records
            for name in (record.pvname, *record.aliases)
        ]
        missing_record_macros = missing_epics_macro_substitutions(
            record_pv_names, macro_values
        )
        if missing_record_macros:
            logger.warning(
                "Skipping PV-length checks because database macros are missing: %s",
                ", ".join(sorted(missing_record_macros)),
            )
        else:
            check_record_pv_lengths(all_records, macro_values)

    db_string = "\n\n".join(package.render() or "" for package in packages)
    if packages:
        with open(path, "w") as fp:
            fp.write(db_string)

    if write_archive_file and packages:
        with open(archive_path, "w") as fp:
            fp.write("\n".join(generate_archive_settings(packages)))

    by_pvname = {
        record.pvname: record for package in packages for record in package.records
    }
    filenames = [str(path)] if packages else []

    if generate_ethercat:
        ethercat_database, _access_config = ethercat.generate_ethercat_files(
            plc.root, path, macro_values
        )
        if ethercat_database is not None:
            filenames.append(str(ethercat_database))
            by_pvname.update(
                {
                    record.pvname: record
                    for package in ethercat_packages
                    for record in package.records
                }
            )
    return filenames, by_pvname


@functools.lru_cache
def get_linter_results(plc: parser.Plc) -> dict[str, Any]:
    """
    Lint the provided PLC code pragmas.

    Returns
    -------
    dict
        Includes "pragma_count", "pragma_errors", and "linter_results" keys.
    """
    pragma_count = 0
    linter_errors = 0
    results = []

    for fn, source in plc.source.items():
        for info in pragmalint.lint_source(fn, source):
            pragma_count += 1
            if info.exception is not None:
                linter_errors += 1
                results.append(info)

    return {
        "pragma_count": pragma_count,
        "pragma_errors": linter_errors,
        "linter_results": results,
    }


def config_to_pragma(
    config: dict, skip_desc: bool = True, skip_pv: bool = True
) -> Generator[tuple[str, str], None, None]:
    """
    Convert a configuration dictionary into a single pragma string.

    Yields
    ------
    key: str
        Pragma key.

    value: str
        Pragma value.
    """
    if not config:
        return

    for key, value in config.items():
        if key == "archive":
            seconds = value.get("seconds", "unknown")
            method = value.get("method", "unknown")
            fields = value.get("fields", {"VAL"})
            if seconds != 1 or method != "scan":
                yield ("archive", f"{seconds}s {method}")
            if fields != {"VAL"}:
                yield ("archive_fields", " ".join(fields))
        elif key == "update":
            frequency = value.get("frequency", 1)
            method = value.get("method", "unknown")
            if frequency != 1 or method != "poll":
                yield (key, f"{frequency}hz {method}")
        elif key == "field":
            for field, value in value.items():
                if field != "DESC" or not skip_desc:
                    yield ("field", f"{field} {value}")
        elif key == "pv":
            if not skip_pv:
                yield (key, ":".join(value))
        else:
            yield (key, value)


@functools.lru_cache
def get_library_versions(plc: parser.Plc) -> dict[str, dict[str, Any]]:
    """Get library version information for the given PLC."""

    def find_by_name(cls_name):
        try:
            cls = parser.TWINCAT_TYPES[cls_name]
        except KeyError:
            return []
        else:
            return list(plc.find(cls, recurse=False))

    versions = {}

    for category in (
        "PlaceholderReference",
        "PlaceholderResolution",
        "LibraryReference",
    ):
        for obj in find_by_name(category):
            info = obj.get_resolution_info()
            info["category"] = category
            if info["name"] not in versions:
                versions[info["name"]] = {}

            versions[info["name"]][category] = info

    return versions


def render_template(
    template: str, context: dict, trim_blocks=True, lstrip_blocks=True, **env_kwargs
):
    """
    One-time-use jinja environment + template rendering helper.
    """
    env = jinja2.Environment(
        loader=jinja2.DictLoader({"template": template}),
        trim_blocks=trim_blocks,
        lstrip_blocks=lstrip_blocks,
        **env_kwargs,
    )

    env.filters.update(get_jinja_filters())
    return env.get_template("template").render(context)


