def get_render_context() -> dict[str, Any]:
    """Jinja template context dictionary - helper functions."""
    context = {func.__name__: func for func in helpers}
    context["types"] = parser.TWINCAT_TYPES
    context["pytmc_version"] = pytmc_version
    return context


def _split_macro(macro: str) -> tuple[str, str]:
    """
    Split a macro of the form NAME=VALUE into ("NAME", "VALUE").

    Parameters
    ----------
    macro : str
        The raw macro string.

    Returns
    -------
    name : str
    value : str
    """
    parts = macro.split("=", 1)
    if len(parts) != 2:
        raise ValueError(f"Macro not in the format ``NAME=VALUE``: {macro!r}")
    return tuple(parts)


def split_input_output(arg: str) -> tuple[str, str]:
    """
    Split user-specified template argument into input/output file.

    Parameters
    ----------
    arg : str
        The user-specified command-line argument for ``--template``.

    Returns
    -------
    input_filename : str
        The input filename.
    output_filename : str
        The output filename.  Empty filename implies stdout.
    """
    delim = ":"

    # A Windows drive letter (e.g. "C:") isn't the input/output delimiter;
    # strip it before counting delimiters and re-attach it to the input
    # filename. The lookahead requires a following separator so a real
    # single-letter filename (e.g. "a:b") is never mistaken for one.
    drive_match = re.match(r"^[A-Za-z]:(?=[\\/])", arg)
    if drive_match:
        drive = drive_match.group(0)
        rest = arg[len(drive):]
    else:
        drive = ""
        rest = arg

    num_delim = rest.count(delim)
    if num_delim == 0:
        # Without a delimiter, assume the file is the template filename
        # and the user wants to write to standard output
        return drive + rest, ""

    if num_delim == 1:
        # Our job is easy in this scenario
        input_part, output_part = rest.split(delim, 1)
        return drive + input_part, output_part

    input_parts = rest.split(delim)
    if input_parts[0] == "-":
        # Special case: - as input file means read /dev/stdin
        return "-", delim.join(input_parts[1:])

    output_parts = []
    while input_parts:
        input_filename = drive + delim.join(input_parts)
        if os.path.exists(input_filename):
            return input_filename, delim.join(output_parts)
        output_parts.insert(0, input_parts.pop(-1))

    raise ValueError(
        f"Invalid input: {arg!r} should be in the format "
        f"'input_filename:output_filename' but input filenames were "
        f"found that matched"
    )


def resolve_motors(template_args: dict) -> dict[str, Any]:
    """
    Given template_args (with macros and 'projects'), resolve the correct motors lists
    for legacy and FB_MotionStage, enforcing that only one family is present.
    Returns a context dict for updating template_args.
    """
    plc_name = template_args.get("plc", None)
    projects_dict = template_args["projects"]

    if plc_name is not None:
        project, plc = get_plc_by_name(projects_dict, plc_name)
        if plc is None:
            raise RuntimeError(f"PLC '{plc_name}' not found in loaded projects!")
    else:
        # Default: take first PLC from the first project found (safe for single-PLC projects)
        project = next(iter(projects_dict.values()))
        plcs = list(project.plcs)
        plc = plcs[0]

    legacy_motors = get_legacy_motors(plc)
    stream_motors = get_stream_motors(plc)

    if legacy_motors and stream_motors:
        raise RuntimeError(
            f"Both legacy (ST_MotionStage) motors and stream (FB_MotionStage) motors are present. "
            f"Not allowed! Legacy: {[m.name for m in legacy_motors]}, Stream: {[m.name for m in stream_motors]}"
        )

    motors = legacy_motors if legacy_motors else stream_motors

    return {
        "legacy_motors": legacy_motors,
        "stream_motors": stream_motors,
        "motors": motors,
    }


def main(
    projects: list[parser.AnyPath],
    templates: Optional[Union[list[str], str]] = None,
    macros: Union[list[str], dict[str, str], None] = None,
    debug: bool = False,
) -> dict[str, str]:
    """
    Render template(s) based on a TwinCAT3 project, or XML-format file such as TMC.

    Args:
        projects: List of project paths (.sln, .tsproj, .tmc, ...)
        templates: Input template(s) (default: stdin; can be list or single string with [:] for output)
        macros: Dict or list of "MACRO=VALUE" items, e.g., "plc=MyPLC"
        debug: Interactive Python debug after render

    Returns:
        all_rendered: Dict mapping input template to rendered output (string)
    """
    macros = macros or {}
    if not isinstance(macros, dict):
        macros = dict(_split_macro(macro) for macro in macros)

    try:
        ethercat_state_scan_seconds = int(
            macros.get(
                "ethercat_state_scan_seconds",
                ethercat.DEFAULT_ECAT_STATE_SCAN_SECONDS,
            )
        )
    except (TypeError, ValueError) as ex:
        raise ValueError(
            "EtherCAT state scan interval must be a positive number of seconds"
        ) from ex

    if ethercat_state_scan_seconds <= 0:
        raise ValueError(
            "EtherCAT state scan interval must be a positive number of seconds"
        )

    logger.debug("Macros: %s", macros)
    if not templates:
        templates = ["-"]
    if isinstance(templates, str):
        templates = [templates]

    all_rendered = {}

    for template in templates:
        input_filename, output_filename = split_input_output(template)
        if input_filename == "-":
            is_tty = os.isatty(sys.stdin.fileno())
            if is_tty:
                logger.warning("Reading template from standard input...")
                logger.warning("Press ^D on a blank line when done.")
            template_text = sys.stdin.read()
            if is_tty:
                logger.warning("Read template from standard input (len=%d)", len(template_text))
        else:
            with open(input_filename) as fp:
                template_text = fp.read()

        stashed_exception = None
        try:
            template_args = get_render_context()
            template_args.update(projects_to_dict(*projects))
            template_args.update(**macros)
            template_args["ethercat_state_scan_seconds"] = (
                ethercat_state_scan_seconds
            )

            # updating template_args with motors
            template_args.update(resolve_motors(template_args))

            rendered = render_template(template_text, template_args)
        except Exception as ex:
            stashed_exception = ex
            rendered = None

        if not debug:
            if stashed_exception is not None:
                raise stashed_exception
            if output_filename:
                with open(output_filename, "w") as fp:
                    print(rendered, file=fp)
            else:
                print(rendered)
        else:
            message = ["Variables: projects, template_text, rendered, template_args. "]
            if stashed_exception is not None:
                message.append(f"Exception: {type(stashed_exception)} {stashed_exception}")
            util.python_debug_session(namespace=locals(), message="\n".join(message))
        all_rendered[input_filename] = rendered

    return all_rendered
